import json,os
from pathlib import Path
EXPECTED=[[511059, 4081605], [511066, 4081606], [511562, 4081758], [511563, 4081758], [511649, 4081828], [1281494, 16828124]]
def ident(pid):
 f=Path('/proc',str(pid),'stat').read_bytes().rpartition(b') ')[2].split()
 if len(f)<20:raise RuntimeError('proc stat shape')
 return int(f[19])
rows=[]
for pid,start in EXPECTED:
 if ident(pid)!=start:raise RuntimeError('PID identity drift')
 ns=os.readlink('/proc/%s/ns/mnt'%pid)
 raw=Path('/proc',str(pid),'mountinfo').read_text()
 selected=[line for line in raw.splitlines() if len(line.split())>=10 and line.split()[2]=='7:36']
 if ident(pid)!=start:raise RuntimeError('PID identity drift after read')
 rows.append(dict(pid=pid,starttime=start,mount_namespace=ns,matching_rows=selected))
print(json.dumps(dict(status='EXACT_NAMESPACE_LINK_GAP_READONLY',rows=rows)))
